/*
 * audioctl_abi.h -- local mirror of the kernel ABI sonosd drives.
 *
 * Copied from the Sonos GPL drop (kernel 2.6.35), files:
 *     drivers/audiodev/dspdev.h        DSPDEV_*   -- /dev/dsp   (PCM out + DSP)
 *     drivers/audiodev/audioctl.h      AUDIOCTL_* -- /dev/audioctl (mute, LEDs, temp)
 *     drivers/audiodev/audioctl_pub.h  AUDIOCTL_MAJOR
 *
 * These are GPL v2 constants copied verbatim. Do not "tidy" the numbers: they
 * are the on-the-wire ABI of a shipped, unmodifiable kernel module.
 *
 * The ioctl *encoding* is generated by <sys/ioctl.h> at compile time, not hard
 * coded. That matters on PowerPC, which lays out the direction bits differently
 * from asm-generic (_IOC_NONE=1, _IOC_WRITE=2, _IOC_READ=4). Building this file
 * with the e300c3 cross compiler therefore produces the same numbers the target
 * kernel computes.
 *
 * Not in the GPL drop: the handlers for DSP_SYS_GET_VOLUME / SET_VOLUME /
 * GET_RVOLUME / SET_RVOLUME / SET_VOLUME_NO_RAMP / FILTER_LEVEL / FILTER_ENABLE
 * are absent from every .c file in the drop (they live in the closed
 * audiodev.ko). The ioctl numbers and sizes below are authoritative; the
 * *payload layout* of FILTER_LEVEL (12 bytes) and FILTER_ENABLE (8 bytes) is
 * inferred as three and two 32-bit words respectively and is marked ASSUMED at
 * each use site. Verify on hardware before trusting it.
 */

#ifndef SONOSD_AUDIOCTL_ABI_H
#define SONOSD_AUDIOCTL_ABI_H

#include <sys/ioctl.h>
#include <stdint.h>

/* ---- dspdev.h -------------------------------------------------------- */

#define DSPDEV_MAJOR            250

#define DSP_SYS_NOP             0
#define DSP_SYS_ECHO            1
#define DSP_SYS_FLUSH           2
#define DSP_SYS_DATA_XFR_OPS    8
#define DSP_SYS_READY           9
#define DSP_SYS_GET_TOD         10
#define DSP_SYS_GET_BYTE_PTR    11
#define DSP_SYS_RESET           12
#define DSP_SYS_FILTER_LEVEL    15
#define DSP_SYS_FILTER_ENABLE   16
#define DSP_SYS_FLUSH_INPUT     20

#define DSP_SYS_GET_VOLUME      21
#define DSP_SYS_SET_VOLUME      22
#define DSP_SYS_GET_RVOLUME     23
#define DSP_SYS_SET_RVOLUME     24
#define DSP_SYS_SET_VOLUME_NO_RAMP 25

#define DSP_SYS_RESET_TX_ORUN   32
#define DSP_SYS_GET_TX_ORUN     33
#define DSP_SYS_RESET_RX_ORUN   34
#define DSP_SYS_GET_RX_ORUN     35
#define DSP_SYS_SET_PWM         36
#define DSP_SYS_GET_PWM         37
#define DSP_SYS_DRAIN           39
#define DSP_SYS_GET_FREE        40

#define DSPDEV_ECHO              _IOW(DSPDEV_MAJOR, DSP_SYS_ECHO, int)
#define DSPDEV_FLUSH             _IO(DSPDEV_MAJOR,  DSP_SYS_FLUSH)
#define DSPDEV_GET_TOD           _IOR(DSPDEV_MAJOR, DSP_SYS_GET_TOD, long long)
#define DSPDEV_GET_BYTE_PTR      _IOR(DSPDEV_MAJOR, DSP_SYS_GET_BYTE_PTR, int)
#define DSPDEV_FILTER_LEVEL      _IOC(_IOC_WRITE, DSPDEV_MAJOR, DSP_SYS_FILTER_LEVEL, 12)
#define DSPDEV_FILTER_ENABLE     _IOC(_IOC_WRITE, DSPDEV_MAJOR, DSP_SYS_FILTER_ENABLE, 8)
#define DSPDEV_FLUSH_INPUT       _IO(DSPDEV_MAJOR,  DSP_SYS_FLUSH_INPUT)
#define DSPDEV_GET_VOLUME        _IOR(DSPDEV_MAJOR, DSP_SYS_GET_VOLUME, int)
#define DSPDEV_SET_VOLUME        _IOW(DSPDEV_MAJOR, DSP_SYS_SET_VOLUME, int)
#define DSPDEV_GET_RVOLUME       _IOR(DSPDEV_MAJOR, DSP_SYS_GET_RVOLUME, int)
#define DSPDEV_SET_RVOLUME       _IOW(DSPDEV_MAJOR, DSP_SYS_SET_RVOLUME, int)
#define DSPDEV_SET_VOLUME_NO_RAMP _IOW(DSPDEV_MAJOR, DSP_SYS_SET_VOLUME_NO_RAMP, int)
#define DSPDEV_RESET_TX_ORUN     _IO(DSPDEV_MAJOR,  DSP_SYS_RESET_TX_ORUN)
#define DSPDEV_GET_TX_ORUN       _IOR(DSPDEV_MAJOR, DSP_SYS_GET_TX_ORUN, int)
#define DSPDEV_RESET_RX_ORUN     _IO(DSPDEV_MAJOR,  DSP_SYS_RESET_RX_ORUN)
#define DSPDEV_GET_RX_ORUN       _IOR(DSPDEV_MAJOR, DSP_SYS_GET_RX_ORUN, int)
#define DSPDEV_DRAIN             _IO(DSPDEV_MAJOR,  DSP_SYS_DRAIN)
#define DSPDEV_GET_FREE          _IOR(DSPDEV_MAJOR, DSP_SYS_GET_FREE, unsigned long)

/* ---- audioctl_pub.h -------------------------------------------------- */

#define AUDIOCTL_MAJOR          252
#define BUTTON_DEVICE           "/dev/audioctl"

/* ---- audioctl.h (subset we use) -------------------------------------- */

#define AUDIODEV_CTL_LINE_MUTE              4
#define AUDIODEV_CTL_AMP_MUTE               12
#define AUDIODEV_CTL_CS42416_MUTE           16
#define AUDIODEV_CTL_CS42416_GET_VOLUME     17
#define AUDIODEV_CTL_CS42416_SET_VOLUME     18
#define AUDIODEV_CTL_VERSION_QUERY          29
#define AUDIODEV_CTL_TEMPERATURE            30
#define AUDIODEV_CTL_SYSTEM_STATUS          44
#define AUDIODEV_R8OP_LED_REQUEST           144
#define AUDIODEV_R8OP_LED_FUNC              155

#define AUDIOCTL_LINE_MUTE              _IOW(AUDIOCTL_MAJOR, AUDIODEV_CTL_LINE_MUTE, int)
#define AUDIOCTL_AMP_MUTE               _IOW(AUDIOCTL_MAJOR, AUDIODEV_CTL_AMP_MUTE, int)
#define AUDIOCTL_CS42416_MUTE           _IOW(AUDIOCTL_MAJOR, AUDIODEV_CTL_CS42416_MUTE, int)
#define AUDIOCTL_CS42416_GET_VOLUME     _IOWR(AUDIOCTL_MAJOR, AUDIODEV_CTL_CS42416_GET_VOLUME, int)
#define AUDIOCTL_CS42416_SET_VOLUME     _IOW(AUDIOCTL_MAJOR, AUDIODEV_CTL_CS42416_SET_VOLUME, int)
#define AUDIOCTL_VERSION_QUERY          _IOR(AUDIOCTL_MAJOR, AUDIODEV_CTL_VERSION_QUERY, int)
#define AUDIOCTL_SYSTEM_STATUS          _IOR(AUDIOCTL_MAJOR, AUDIODEV_CTL_SYSTEM_STATUS, int)
#define AUDIOCTL_TEMPERATURE            _IOR(AUDIOCTL_MAJOR, AUDIODEV_CTL_TEMPERATURE, int[3])
#define AUDIOCTL_R8OP_LED_REQUEST       _IOW(AUDIOCTL_MAJOR, AUDIODEV_R8OP_LED_REQUEST, int)
#define AUDIOCTL_R8OP_LED_FUNC          _IOW(AUDIOCTL_MAJOR, AUDIODEV_R8OP_LED_FUNC, struct led_func)

/* AUDIOCTL_SYSTEM_STATUS bits (audioctl.h SYSTAT_*) */
#define SYSTAT_AMP_MUTE_STATUS              0x00000200
#define SYSTAT_AMP_FAULT_STATUS             0x00000004
#define SYSTAT_AMP_THERMAL_FAULT_STATUS     0x00000010
#define SYSTAT_AMP_OVLD_FAULT_STATUS        0x00000040
#define SYSTAT_AMP_PWR_STATUS               0x00000100

struct led_func {
    unsigned char   led_slot[8];
    unsigned int    led_flags;
};

#define AUDIODEV_R8OP_LED_FUNC_RESTART      0x00000001

/* LED bitmask values, audioctl.h */
#define LED_WHITE           1
#define LED_GREEN           2
#define LED_AMBER           4
#define LED_RED             8
#define LED_GREEN_BUTTON    0x10
#define LED_OVERRIDE        0x20

/* ---- payload layouts we define --------------------------------------- *
 *
 * 12-byte DSPDEV_FILTER_LEVEL: three native 32-bit words. Name and order are
 * ASSUMED (see file header). Kept as int32_t, not int, so the struct size is
 * 12 on both the 32-bit target and a 64-bit build host.
 *
 * 8-byte DSPDEV_FILTER_ENABLE: two native 32-bit words, two on/off flags.
 */
struct dsp_filter_level {
    int32_t bass;       /* -10 .. +10 */
    int32_t treble;     /* -10 .. +10 */
    int32_t balance;    /* -10 (left) .. +10 (right) */
};

struct dsp_filter_enable {
    int32_t loudness;   /* 0/1 */
    int32_t night_mode; /* 0/1 */
};

/* Compile-time check that the payload sizes still match the ioctl sizes. The
 * kernel copies exactly _IOC_SIZE() bytes, so a mismatch would silently move
 * the wrong words. C99 has no _Static_assert; a negative array size is the
 * portable equivalent. */
typedef char sonosd_abi_check_filter_level[(sizeof(struct dsp_filter_level) == 12u) ? 1 : -1];
typedef char sonosd_abi_check_filter_enable[(sizeof(struct dsp_filter_enable) == 8u) ? 1 : -1];
typedef char sonosd_abi_check_led_func[(sizeof(struct led_func) == 12u) ? 1 : -1];

#endif /* SONOSD_AUDIOCTL_ABI_H */
